    37→
    38→# Helper function to check if R2 backup is newer than local
    39→should_restore_from_r2() {
    40→    local R2_SYNC_FILE="$BACKUP_DIR/.last-sync"
    41→    local LOCAL_SYNC_FILE="$CONFIG_DIR/.last-sync"
    42→    
    43→    # If no R2 sync timestamp, don't restore
    44→    if [ ! -f "$R2_SYNC_FILE" ]; then
    45→        echo "No R2 sync timestamp found, skipping restore"
