    53→    fi
    54→    
    55→    # Compare timestamps
    56→    R2_TIME=$(cat "$R2_SYNC_FILE" 2>/dev/null)
    57→    LOCAL_TIME=$(cat "$LOCAL_SYNC_FILE" 2>/dev/null)
    58→    
    59→    echo "R2 last sync: $R2_TIME"
