    61→    
    62→    # Convert to epoch seconds for comparison
    63→    R2_EPOCH=$(date -d "$R2_TIME" +%s 2>/dev/null || echo "0")
    64→    LOCAL_EPOCH=$(date -d "$LOCAL_TIME" +%s 2>/dev/null || echo "0")
    65→    
