    18→}
    19→function resolveDefaultRuntime(channelId) {
    20→    const plugin = getChannelPlugin(channelId);
    21→    return plugin?.status?.defaultRuntime ?? { accountId: DEFAULT_ACCOUNT_ID };
    22→}
    23→function cloneDefaultRuntime(channelId, accountId) {
    24→    return { ...resolveDefaultRuntime(channelId), accountId };
    25→}
    26→// Channel docking: lifecycle hooks (`plugin.gateway`) flow through this manager.
    27→export function createChannelManager(opts) {
    28→    const { loadConfig, channelLogs, channelRuntimeEnvs } = opts;
    29→    const channelStores = new Map();
    30→    const getStore = (channelId) => {
    31→        const existing = channelStores.get(channelId);
    32→        if (existing)
    33→            return existing;
    34→        const next = createRuntimeStore();
    35→        channelStores.set(channelId, next);
    36→        return next;
    37→    };
    38→    const getRuntime = (channelId, accountId) => {
    39→        const store = getStore(channelId);
    40→        return store.runtimes.get(accountId) ?? cloneDefaultRuntime(channelId, accountId);
    41→    };
    42→    const setRuntime = (channelId, accountId, patch) => {
    43→        const store = getStore(channelId);
    44→        const current = getRuntime(channelId, accountId);
    45→        const next = { ...current, ...patch, accountId };
    46→        store.runtimes.set(accountId, next);
    47→        return next;
    48→    };
    49→    const startChannel = async (channelId, accountId) => {
    50→        const plugin = getChannelPlugin(channelId);
    51→        const startAccount = plugin?.gateway?.startAccount;
    52→        if (!startAccount)
    53→            return;
