    56→        const store = getStore(channelId);
    57→        const accountIds = accountId ? [accountId] : plugin.config.listAccountIds(cfg);
    58→        if (accountIds.length === 0)
    59→            return;
    60→        await Promise.all(accountIds.map(async (id) => {
    61→            if (store.tasks.has(id))
    62→                return;
    63→            const account = plugin.config.resolveAccount(cfg, id);
    64→            const enabled = plugin.config.isEnabled
    65→                ? plugin.config.isEnabled(account, cfg)
    66→                : isAccountEnabled(account);
    67→            if (!enabled) {
    68→                setRuntime(channelId, id, {
    69→                    accountId: id,
    70→                    running: false,
    71→                    lastError: plugin.config.disabledReason?.(account, cfg) ?? "disabled",
    72→                });
    73→                return;
    74→            }
    75→            let configured = true;
    76→            if (plugin.config.isConfigured) {
    77→                configured = await plugin.config.isConfigured(account, cfg);
    78→            }
    79→            if (!configured) {
    80→                setRuntime(channelId, id, {
    81→                    accountId: id,
    82→                    running: false,
    83→                    lastError: plugin.config.unconfiguredReason?.(account, cfg) ?? "not configured",
    84→                });
    85→                return;
    86→            }
    87→            const abort = new AbortController();
    88→            store.aborts.set(id, abort);
    89→            setRuntime(channelId, id, {
